def find_W(k):
    for c1 in range(2):
        for c2 in range(2):
            if c1 == 0 and c2 == 0:
                continue
            sequence = [1 for _ in range(k)]
            period = 2**k - 1

            for n in range(1, period):
                a_n = sum(c * sequence[k - n] for c, sequence in zip((c1, c1 ** (k - 1)), sequence)) % 2
                sequence.pop(0)
                sequence.append(a_n)

            if len(sequence) == period:
                return c1, c2
    return -1

