MOD = 10**9 + 9

class FenwickTree:
    def __init__(self, size):
        self.tree = [0] * (size + 1)

    def update(self, i, val):
        while i <= len(self.tree):
            self.tree[i] = (self.tree[i] + val) % MOD
            i += i & -i

    def query(self, i):
        result = 0
        while i > 0:
            result = (result + self.tree[i]) % MOD
            i -= i & -i
        return result

class Solution:
    def solve(self, queries):
        result = [0] * len(queries)
        dp = [1, 1]
        for i in range(len(queries)):
            if queries[i][0] == 1:
                l, r = queries[i][1] - 1, queries[i][2] - 1
                num = queries[i][3] - l
                new_dp = dp[:]
                for j in range(l, r + 1):
                    new_dp[j] = (new_dp[j] + num * dp[j - l]) % MOD
                length = len(dp)
                dp, tmp = [0] * length, new_dp[:]
                for j in range(1, length):
                    dp[j] = (dp[j - 1] + dp[j]) % MOD
                dp = tmp
            else:
                l, r = queries[i][1] - 1, queries[i][2] - 1
                i = dp[(r + 1) // 2]
                result[i] = (dp[::-1][l] - dp[::-1][r - 1]) % MOD
        return result
