    visited[(x1, y1)] = 1
    while queue:
        x, y = queue.pop(0)
        if (x2, y2) in graph[(x, y)]:
            return True
        for neighbour in graph[(x, y)]:
            if visited[(neighbour, y)] == 0:
                queue.append((neighbour, y))
                visited[(neighbour, y)] = 1
    return False

