def LucasSequence(k):
    if k <= 2:
        return -1
    else:
        c_coefficients = [1] * k
        a = [0] + [1] * (k - 1)

        while True:
            next_row = [0] * k
            for i in range(k):
                if a[i] == 1:
                    next_row[i] = 1
                    for j in range(i + 1, k):
                        next_row[(i - j + k) % k] = (next_row[(i - j + k) % k] + j * c_coefficients[j]) % 2
            if all(x == 1 for x in next_row):
                break
            c_coefficients = next_row
            a = next_row

    sequence = ['.'] * (2**k - 1) + ['.']
    sequence.extend(a)
    sequence = sequence[:2**k - 1]

    return "\n".join(map(str, c_coefficients)), ''.join(map(str, sequence))

