import math

def is_square(x):
    s = int(math.sqrt(x))
    return s * s == x

def count_right_permutations(n, a):
    mod = 10 ** 9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for num in a:
        next_dp = [0] * (n + 1)
        for i in range(n):
            for j in range(i + 1):
                if is_square(num * j * (j + 1)) and i - j >= 0:
                    break
                next_dp[i + 1] += dp[j] * (i - j + 1)
                next_dp[i + 1] %= mod
        dp = next_dp[:]
    return dp[n]

