                    heappush(complements, (a[2] + a[2], tuple(api(sorted(a[2:])[:a[2]]))))
                else:
                    break
                if visible == N:
                    break

            complement = heappop(complements)
            for j in range(len(elements)):
                e = elements[j]
                if e[2] == complement[0][0]:
