                    visible -= total_skill[e[1]] - choose
                    complements.append((choose + e[2], choose + (min(interse(a, b) for a, b in zip(sorted(e[2:], [choose]), sorted(choosable_indices))))[0]))
                    heappush(elements, e, indices=choosable_indices)

        for k in range(i - 1, len(data), -1 - i - 1):
            e = data.pop(data[k][-1][-1])
            target = tuple(reversed(total_skill[k][-1]))
