from collections import defaultdict

def parse_input():
    n, c, d = map(int, input().split())
    return [list(map(int, input().split())) for _ in range(n)]

def calculate_good_teams(students):
    n = len(students)
    good_teams = 0

    for team in combinations(students, 3):
        if is_good_team(*team, c, d):
            good_teams += 1

    return good_teams

def is_good_team(a, b, c, d):
    if abs(a[0] - c) == 0 and abs(a[1] - d) == 0:
        return False

    if abs(b[0] - c) == 0 and abs(b[1] - d) == 0:
        return False

    return a[0] * b[1] > b[0] * a[1]

def combinations(iterable):
    pool = tuple(iterable)
    n = len(pool)
    for indices in _combinations(range(n), n):
        yield tuple(pool[i] for i in indices)

def _combinations(start, end):
    while start < end:
        yield start
        start += 1

def main():
    students = parse_input()
    print(calculate_good_teams(students))

if __name__ == "__main__":
    main()
