import sys

def clean_hallway(n, m, workers):
    intervals = []
    for worker_i in range(m):
        L_i, R_i = map(int, workers.split()[worker_i].strip().split())
        intervals.append([L_i, L_i + R_i - 1])
        intervals.append([R_i, R_i + L_i - 1])
    # Sort the intervals by start time
    intervals.sort()
    stack = [0]
    for i in range(1, n):
        if intervals[i][0] < stack[-1][1] + 1:
            stack.append(i)
        elif intervals[i][1] < stack[-1][1] + 1:
            stack.pop()
    if stack:
        return n - 1
    else:
        return -1

