def count_superior_subarrays(n, a):
    from collections import defaultdict
    count = defaultdict(int)
    for i in range(n):
        subarray = tuple(a[i:i+n:i])
        if count[subarray] == 0:
            count[subarray] = 1
        for s in range(n):
            if s > i or math.gcd(s, n) > 1:
                break
            if subarray == tuple(a[(i+j) % n:s+j:n] for j in range(min(s,n))):
                return 0
    return len(count)

