mod = 998244353

def power_mod(base, exponent, mod):
    result = 1
    base = base % mod
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % mod
        exponent = exponent >> 1
        base = (base * base) % mod
    return result

def count_trees(x, y, n, t, mod):
    if x < 0 or y < 0:
        return 0
    if x == y == 0:
        return n
    return power_mod(n + 2, t, mod)

def calculate_destructive_power(n, t):
    total_val = 0
    for _ in range(n - 2):
        total_val = (total_val + count_trees(n - 1, n, t, mod)) % mod
    return total_val

def main():
    n, t = map(int, input().split())
    initial_positions = [list(map(int, input().split())) for _ in range(n)]
    result = calculate_destructive_power(n, t)
    print(result)

