def count_superior_p_subs(n, nums):
    s = 1 << n
    mask = 1 << (n - 1)
    position = 0
    count = 0
    iteration = True
    for _ in range(n):
        if iteration:
            for i in range(mask):
                position += 1
                ps = mask ^ (1 << i) | mask
                for j in range(n):
                    ps = ps | (ps >> (s * j))
                if ps & position != 0 or (mask - 1) & ps == 0:
                    count += 1
            iteration = False
        else:
            for i in range(mask):
                position += 1
                ps = mask ^ (1 << i) | mask
                ps = ps | ((mask ^ (1 << (mask.bit_length() - 1))) - 1)
                for sss in range(n):
                    kkk = ps ^ mask
                    if ((sss - n // 2 + kkk) // mask & mask):
                        continue
                    for j in range(n):
                        ps = ps | ((sss - n // 2 + mask) | (ps >> (s * j)))
                        if ((sss - n // 2) & ps) == 0:
                            count += 1
            iteration = True
    return count

