from math import gcd
from itertools import starmap, count

def lcm(x, y):
    return x * y // gcd(x, y)

def lcm_range(n, ranges):
    least_common_multiple = n
    for range_tuple in ranges:
        least_common_multiple = lcm(least_common_multiple, range_tuple[-1])
    return least_common_multiple

def solve(num_elements, elements):
    ranges = []
    for i in range(num_elements):
        start = elements[i]
        range_start = i
        range_end = num_elements
        while range_start != range_end:
            if not starmap(start <= _, [(elements[j] for j in range(range_start, range_end)))]:
                break
            range_start += 1
            range_end += 1
        else:
            range_length = range_end - range_start + 1
            first = (range_start, range_length)
            second = (range_start + range_length, range_length)
            ranges += [first, second]
    return len(ranges)

n = int(input().strip())
